import { chromium, devices } from 'playwright';
import { createServer } from 'node:http';
import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
const files=new Map();
for(const id of ['reverse-grip-pushdown'])for(const suffix of ['']){const name=id+suffix+'.mp4';files.set('/'+name,readFileSync('public/exercise-guides/ai-v3/'+name));}
const server=createServer((req,res)=>{const data=files.get(req.url);if(!data){res.writeHead(404);res.end();return;}const range=req.headers.range?.match(/^bytes=(\d+)-(\d*)$/);if(range){const start=Number(range[1]),end=range[2]?Number(range[2]):data.length-1;res.writeHead(206,{'Content-Type':'video/mp4','Accept-Ranges':'bytes','Content-Range':`bytes ${start}-${end}/${data.length}`,'Content-Length':end-start+1});res.end(data.subarray(start,end+1));}else{res.writeHead(200,{'Content-Type':'video/mp4','Accept-Ranges':'bytes','Content-Length':data.length});res.end(data);}});
await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
let browser;
const results=[];
try{browser=await chromium.launch({headless:true});const context=await browser.newContext({...devices['Pixel 7']});for(const [name,data] of files){const page=await context.newPage();await page.goto(`http://127.0.0.1:${server.address().port}${name}`);await page.waitForFunction(()=>document.querySelector('video')?.readyState>=2);const meta=await page.locator('video').evaluate(async v=>{v.muted=true;await v.play();return{width:v.videoWidth,height:v.videoHeight,seconds:v.duration};});if(meta.width!==480||meta.height!==480||Math.abs(meta.seconds-8)>.05)throw Error('Unexpected format');await page.waitForFunction(()=>document.querySelector('video').currentTime>.15);await page.locator('video').evaluate(v=>{v.pause();v.currentTime=7.5;});await page.waitForFunction(()=>{const v=document.querySelector('video');return !v.seeking&&v.readyState>=2&&!v.error;});results.push({name,...meta,sha256:createHash('sha256').update(data).digest('hex'),play:'passed',seek:'passed'});await page.close();}writeFileSync('tools/media/imports/playback-pushdown-20260920.json',JSON.stringify({checkedAt:new Date().toISOString(),scope:'Frozen local MP4 buffers on loopback HTTP, mobile Chromium; not app layout or physical Android',results},null,2));console.log(JSON.stringify(results));}finally{if(browser)await browser.close();await new Promise(resolve=>server.close(resolve));}
